 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string source="Assets/Afrer_Seconds/06.Data/AssetSources/B4_ExperimentOperations_20261108.json";AssetDatabase.ImportAsset(source,ImportAssetOptions.ForceSynchronousImport);
